// Prefix-answer DP, rolling variables: House Robber. O(n) time, O(1) space.
int rob(const vector<int>& a) {
    int prev2 = 0, prev1 = 0;                  // dp[i-2], dp[i-1] for an empty prefix
    for (int x : a) {
        int cur = max(prev1, prev2 + x);       // skip i, or rob i on top of dp[i-2]
        prev2 = prev1; prev1 = cur;
    }
    return prev1;
}

// Ending-at-i DP: Longest Increasing Subsequence, O(n^2) baseline.
int lengthOfLIS(const vector<int>& a) {
    int n = a.size();
    vector<int> dp(n, 1);                      // every element alone is a subsequence
    int best = n ? 1 : 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < i; ++j)
            if (a[j] < a[i]) dp[i] = max(dp[i], dp[j] + 1);
        best = max(best, dp[i]);               // answer is the max over all endings
    }
    return best;
}

// Counting DP: number of ways to reach step n taking 1 or 2 steps (Climbing Stairs).
int climbStairs(int n) {
    long long a = 1, b = 1;                    // ways(0) = 1, ways(1) = 1
    for (int i = 2; i <= n; ++i) { long long c = a + b; a = b; b = c; }
    return (int)b;
}

